const body = $input.first().json.body || {};
const top = Array.isArray(body.top) ? body.top : [];
const fmtDate = (d) => {
  if (!d) return 'no deadline';
  const dt = new Date(d + 'T00:00:00');
  return isNaN(dt) ? d : dt.toLocaleDateString('en-IN', { day: 'numeric', month: 'short' });
};
const lines = [`🎓 ScholarForge digest for ${body.profile_name || 'you'}`, ''];
if (top.length) {
  lines.push('Top picks:');
  top.forEach((t, i) => {
    lines.push(`${i + 1}. ${t.title} — score ${t.score ?? '?'} — due ${fmtDate(t.deadline)}`);
    if (t.url) lines.push(`   ${t.url}`);
  });
} else {
  lines.push('Nothing new you can act on right now.');
}
if (body.flagged_scams) lines.push('', `⚠️ ${body.flagged_scams} likely scam${body.flagged_scams > 1 ? 's' : ''} blocked.`);
lines.push('', `Run ${body.run_id || ''}`);
return [{ json: { text: lines.join('\n').slice(0, 4000) } }];
